// --- FSRS-5 QUALITY RATING SYSTEM ---
function ensureSessionTally() {
  if (!studyState.tally) {
    studyState.tally = { again: 0, hard: 0, good: 0, easy: 0, total: 0, startMs: Date.now() };
  }
  return studyState.tally;
}

function handleAnkiQuality(quality) {
  const filtered = getFilteredCards();
  const currentCard = filtered[studyState.currentIndex];
  if (!currentCard) return;

  // Find original card object in state to update
  let origCard = findCardInState(currentCard.id);
  if (!origCard) origCard = currentCard;

  const oneDayMs = 24 * 60 * 60 * 1000;
  const preview = getQualityIntervals(origCard);
  const chosen = preview[quality] || preview.good;
  const g = chosen.g || 3;

  // Snapshot para UNDO
  undoState = {
    cardId: origCard.id,
    prev: {
      interval: origCard.interval,
      repetitions: origCard.repetitions,
      easeFactor: origCard.easeFactor,
      dueDate: origCard.dueDate,
      fsrsS: origCard.fsrsS,
      fsrsD: origCard.fsrsD,
      fsrsState: origCard.fsrsState,
      lapses: origCard.lapses,
      lastReviewMs: origCard.lastReviewMs,
      errorCount: origCard.errorCount,
      successCount: origCard.successCount
    },
    quality
  };

  // Contabiliza para o resumo da sessão
  const tally = ensureSessionTally();
  tally[quality] = (tally[quality] || 0) + 1;
  tally.total += 1;

  // Aplica FSRS-5
  origCard.interval = chosen.value;
  origCard.repetitions = chosen.rep;
  origCard.easeFactor = chosen.newEf;
  if (chosen.newS !== undefined) {
    origCard.fsrsS = chosen.newS;
    origCard.fsrsD = chosen.newD;
  } else {
    // Primeira avaliação: estado inicial FSRS S0(G), D0(G)
    origCard.fsrsS = fsrsInitialStability(g);
    origCard.fsrsD = fsrsInitialDifficulty(g);
  }
  origCard.fsrsState = chosen.state || 'review';
  origCard.lastReviewMs = Date.now();

  const deltaMs = Math.round(chosen.value * oneDayMs);
  const nextDueMs = Date.now() + deltaMs;
  origCard.dueDate = nextDueMs;

  // Leech: lapses acumulados (Errei em review = lapse)
  if (quality === 'again') {
    origCard.lapses = (origCard.lapses || 0) + 1;
    origCard.errorCount = (origCard.errorCount || 0) + 1;
  } else if (quality === 'hard') {
    origCard.errorCount = (origCard.errorCount || 0) + 1;
  } else {
    origCard.successCount = (origCard.successCount || 0) + 1;
  }

  // Record in evaluation history log & record study time
  // Meta FSRS para o log (S/D/R pré e pós — insumo do futuro otimizador)
  const _prevS = undoState && undoState.cardId === origCard.id ? (undoState.prev.fsrsS || 0) : 0;
  const _prevD = undoState && undoState.cardId === origCard.id ? (undoState.prev.fsrsD || 5) : 5;
  const _elapsed = origCard.lastReviewMs ? (Date.now() - origCard.lastReviewMs) / 86400000 : 0;
  const fsrsMeta = {
    g: g,
    state: chosen.state || 'review',
    deltaT: Math.round(_elapsed * 100) / 100,
    S_before: _prevS,
    D_before: _prevD,
    R_before: _prevS ? Math.round(fsrsRetrievability(_elapsed, _prevS) * 1000) / 1000 : null,
    S_after: origCard.fsrsS,
    D_after: origCard.fsrsD
  };
  logCardEvaluation(origCard.id, quality, origCard.containerId || studyState.deckId, fsrsMeta);
  recordSessionStudyTime();

  // Increment daily streak for studying at least 1 card
  recordStudyActivity();
  saveState();

  // Format date/hour preview for toast
  const dueDateObj = new Date(nextDueMs);
  const formattedTime = dueDateObj.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  const formattedDate = dueDateObj.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' });
  const leechWarn = origCard.lapses >= FSRS_LEECH_THRESHOLD ? ' ⚠️ Carta marcada como leech!' : '';
  studyState.lastScheduleMsg = `${scheduleTextFor(quality)} daqui ${chosen.label} (${formattedDate} às ${formattedTime})${leechWarn}`;

  // Advance
  studyState.currentIndex += 1;
  studyState.isFlipped = false;
  studyState.userTypedAnswer = '';
  studyState.pedagogicalAnalysis = null;
  renderStudyInterface();
}

function scheduleTextFor(quality) {
  return quality === 'again' ? 'Carta reagendada para' : 'Carta agendada para';
}

// UNDO: restaura o snapshot da última avaliação
let undoState = null;
function undoLastRating() {
  if (!undoState) return;
  const card = findCardInState(undoState.cardId);
  if (!card) { undoState = null; return; }
  Object.assign(card, undoState.prev);
  undoState = null;
  saveState();
  // Volta o cursor para re-avaliar esta carta
  const filtered = getFilteredCards();
  const idx = filtered.findIndex(c => c.id === card.id);
  if (idx >= 0) {
    studyState.currentIndex = idx;
    studyState.isFlipped = true;
    studyState.lastScheduleMsg = '↩️ Avaliação desfeita — avalie novamente.';
  }
  renderStudyInterface();
}

if (studyState.filter === 'cases') {
  list = list.filter(c => c.clinical);
}

// FSRS: vencidas primeiro (mais antigas primeiro), depois novas, depois futuras
const now = Date.now();
const rank = (c) => {
  const due = c.dueDate || 0;
  if (isCardNew(c)) return 2;
  if (due <= now) return 0;
  return 1;
};
list = [...list].sort((a, b) => {
  const ra = rank(a), rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 0) return (a.dueDate || 0) - (b.dueDate || 0);
  return 0;
});
